#!/usr/bin/env bash
portable_env_detect() {
  OS_NAME=$(uname -s)
  SED_BIN=$(command -v sed)
  DATE_BIN=$(command -v date)
  if command -v gsed >/dev/null 2>&1; then SED_PREFIX=g; else SED_PREFIX=''; fi
  if command -v gdate >/dev/null 2>&1; then DATE_PREFIX=g; else DATE_PREFIX=''; fi
  printf 'OS=%s\nSED=%s\nDATE=%s\nSED_PREFIX=%s\nDATE_PREFIX=%s\n' \
    "$OS_NAME" "$SED_BIN" "$DATE_BIN" "$SED_PREFIX" "$DATE_PREFIX"
}
